I have checked it gets down to: `console.log(search);` but I inspect the elements in the debugger and their events are empty and I cannot seem to trigger the button's click

So, I changed my function to be:

``` javascript
var event; // The custom event that will be created
$('#navSearchForm .site-search-input').on('keyup', function(){
    if($('#navSearchForm .site-search-input').val().length <= 0){
        if(document.createEvent){
            event = document.createEvent("Event");
            event.initEvent("click", true, true);
        }else{
            event = document.createEventObject();
            event.eventType = "click";
        }
        event.eventName = "click";

        if(document.createEvent){
            document
                .getElementsByClassName('btn-clear-all-filters')[0]
                .dispatchEvent(event);
        }else{
            document
                .getElementsByClassName('btn-clear-all-filters')[0]
                .fireEvent("on" + event.eventType, event);
        }
    }
});
```
